/* Lookup table for bga data */
typedef struct {
    const char *path;
    const uint8_t *data;
    size_t size;
} EmbeddedEntry;

static const EmbeddedEntry bga_entries[] = {
    { "gfx/bgattr/copyright_screen.bgattr", bga_copyright_screen, 1024 },
    { "gfx/bgattr/erase_all_data.bgattr", bga_erase_all_data, 1024 },
    { "gfx/bgattr/field_select.bgattr", bga_field_select, 576 },
    { "gfx/bgattr/pokedex.bgattr", bga_pokedex, 1024 },
    { "gfx/bgattr/pokedex_2.bgattr", bga_pokedex_2, 1024 },
    { "gfx/bgattr/titlescreen.bgattr", bga_titlescreen, 576 },
};

#define BGA_COUNT (sizeof(bga_entries) / sizeof(bga_entries[0]))

const uint8_t *embedded_bgattr(const char *path, size_t *out_size) {
    for (size_t i = 0; i < BGA_COUNT; i++) {
        if (strcmp(path, bga_entries[i].path) == 0) {
            *out_size = bga_entries[i].size;
            return bga_entries[i].data;
        }
    }
    *out_size = 0;
    return NULL;
}
